import{_ as p,a0 as o,w as r,s as d,I as a,x as t,a1 as i,A as l,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"安裝 elementary OS 6 “Odin” 後要做的 10 件事 | LCTT x X-CMD","titleTemplate":false,"description":"安裝 elementary OS 6 “Odin” 後要做的 10 件事 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝 elementary OS 6 “Odin” 後要做的 10 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝 elementary OS 6 “Odin” 後要做的 10 件事 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin","title":"安裝 elementary OS 6 “Odin” 後要做的 10 件事","tag":"202109","desc":""},"relativePath":"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin.md","filePath":"[post].md"}'),h={name:"202109/20210821 10 Things to Do After Installing elementary OS 6 -Odin.md"};function u(m,e,g,b,k,f){const n=o("Link");return r(),d("div",null,[e[27]||(e[27]=a("h1",{id:"安裝-elementary-os-6-odin-後要做的-10-件事",tabindex:"-1"},[t("安裝 elementary OS 6 “Odin” 後要做的 10 件事 "),a("a",{class:"header-anchor",href:"#安裝-elementary-os-6-odin-後要做的-10-件事","aria-label":"Permalink to “安裝 elementary OS 6 “Odin” 後要做的 10 件事”"},"​")],-1)),e[28]||(e[28]=a("blockquote",null,[a("p",null,"一個精心準備的在安裝 elementary OS 6 “Odin” 後要做的事情的列表。")],-1)),e[29]||(e[29]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202109/04/081345bf9co7ot40szdytg.jpg",alt:""})],-1)),a("p",null,[e[1]||(e[1]=t("在經過兩年多的開發後 ",-1)),i(n,{href:"https://www.debugpoint.com/2021/08/elementary-os-6/"},{default:l(()=>[...e[0]||(e[0]=[t("elementary OS 6 “Odin”",-1)])]),_:1}),e[2]||(e[2]=t(" 於不久前發佈，此次版本更新在核心模組、 Pantheon 桌面、原生應用方面帶來了一大批新特性。elementary OS 6 “Odin” 是基於 Ubuntu 20.04 LTS 的。",-1))]),e[30]||(e[30]=s(`<p>如果你完成了安裝，你可能想要嘗試通過一些特定的設置來使你的系統更加的個性化。這裏描述的選項是通用的，在某些情況下可能對你沒有用，但是我們覺得有必要列出一些基本的東西，讓你有合適的方式來探索這個漂亮的 elementary OS。</p><h3 id="安裝完-elementary-os-6-odin-後要做的事情" tabindex="-1">安裝完 elementary OS 6 “Odin” 後要做的事情 <a class="header-anchor" href="#安裝完-elementary-os-6-odin-後要做的事情" aria-label="Permalink to “安裝完 elementary OS 6 “Odin” 後要做的事情”">​</a></h3><p>準備步驟：</p><p>首先確保你已經連上了互聯網，你可以在頂部的通知區域查看可用的網絡列表</p><h4 id="_1、更改主機名" tabindex="-1">1、更改主機名 <a class="header-anchor" href="#_1、更改主機名" aria-label="Permalink to “1、更改主機名”">​</a></h4><p>這可能不是你想做的第一件事。但是我不知道為什麼在安裝過程中沒有給出更改主機名的選項。例如，見下圖的終端提示， 這個主機名是 elementary OS 的默認硬件配置。在我看來這一點都不好。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/hostname-change-before.jpeg" alt="主機名修改之前"></p><p>打開終端並運行下列命令以更改主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostnamectl set-hostname your-new-hostname</span></span></code></pre></div><p>示例：</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/changing-hostname.jpeg" alt="修改主機名"></p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/changed-hostname.jpeg" alt="主機名修改之後"></p><h4 id="_2、升級你的系統" tabindex="-1">2、升級你的系統 <a class="header-anchor" href="#_2、升級你的系統" aria-label="Permalink to “2、升級你的系統”">​</a></h4><p>在安裝任何 Linux 發行版後，你應該做的第一件事就是確保系統處於最新的軟件包和安全更新狀態。</p><p>你可以通過打開應用中心來檢查或者安裝更新。</p><p>或者打開終端運行下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt upgrade</span></span></code></pre></div><h4 id="_3、安裝-pantheon-tweaks" tabindex="-1">3、安裝 Pantheon Tweaks <a class="header-anchor" href="#_3、安裝-pantheon-tweaks" aria-label="Permalink to “3、安裝 Pantheon Tweaks”">​</a></h4><p>Pantheon Tweaks 是 elementary OS 的必備應用。它提供了一些無法通過系統原生設置程序修改的額外的設置和配置選項，請打開終端並運行以下命令以安裝 Pantheon Tweaks。注意：先前版本的 Tweak 工具叫做 elementary Tweaks，從 Odin 版本開始更名為 Pantheon Tweaks。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install software-properties-common</span></span>
<span class="line"><span>sudo add-apt-repository -y ppa:philip.scott/pantheon-tweaks</span></span>
<span class="line"><span>sudo apt install -y pantheon-tweaks</span></span></code></pre></div><p>安裝後打開系統設置，你可以在那裏找到 “<ruby>調整<rt>Tweaks</rt></ruby>” 選項。</p>`,21)),a("p",null,[i(n,{href:"https://www.debugpoint.com/2021/07/elementary-tweaks-install/"},{default:l(()=>[...e[3]||(e[3]=[t("這裏",-1)])]),_:1}),e[4]||(e[4]=t(" 提供了更詳細的安裝指南（如果你需要了解更多信息）。",-1))]),e[31]||(e[31]=s('<h3 id="_4、配置-dock" tabindex="-1">4、配置 Dock <a class="header-anchor" href="#_4、配置-dock" aria-label="Permalink to “4、配置 Dock”">​</a></h3><p>Dock 是整個桌面的中心。老實説，Dock 中默認包含的應用並不常用，因此你可以通過以下步驟配置 Dock 中的項目。</p><ul><li>移除：右鍵單擊並取消 “<ruby>在 Dock 中駐留<rt>Keep in Dock</rt></ruby>” 選項。</li><li>添加新的項目：單擊頂部的應用程序。然後右鍵單擊你想要放在 Dock 的應用圖標。選擇 “<ruby>添加到 Dock<rt>Add to Dock</rt></ruby>”。</li></ul><p>在我看來，你應該至少把文件管理、截圖工具、Firefox 、計算器，以及其他的一些應用添加到 Dock。然後移除 Dock 上那些你不需要的應用。</p><h4 id="_5、更改外觀" tabindex="-1">5、更改外觀 <a class="header-anchor" href="#_5、更改外觀" aria-label="Permalink to “5、更改外觀”">​</a></h4><p>elementary OS 6 Odin 改進了桌面的整體外觀，為整個桌面和應用程序提供了自帶的強調色和原生的夜間模式，同時，系統自帶了許多漂亮的壁紙。你可以通過 “應用 &gt; 系統設置 &gt; 桌面” 來定製壁紙、外觀、面板和多任務視圖。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/elementary-OS-6-Odin-settings-window-Desktop.jpeg" alt="elementary OS 6 Odin 桌面設置界面"></p><p>按照你希望的樣子來配置你係統的外觀。</p><p>你也可以基於日出和日落的時間來設置夜間模式。</p><h4 id="_6、安裝其他的應用" tabindex="-1">6、安裝其他的應用 <a class="header-anchor" href="#_6、安裝其他的應用" aria-label="Permalink to “6、安裝其他的應用”">​</a></h4><p>自帶的應用中心非常適合這個系統，我發現它是 Linux 桌面最好的應用商店之一。然而，有時候需要安裝沒有預裝的必要應用（大多數是知名的應用）。下面是個新系統推薦安裝的軟件列表。（説真的，為什麼 LibreOffice 沒有預裝？）</p><ul><li>firefox</li><li>gimp</li><li>gedit</li><li>inkscape</li><li>obs-studio</li><li>libreoffice</li></ul><h4 id="_7、一些針對筆記本電腦的省電貼士" tabindex="-1">7、一些針對筆記本電腦的省電貼士 <a class="header-anchor" href="#_7、一些針對筆記本電腦的省電貼士" aria-label="Permalink to “7、一些針對筆記本電腦的省電貼士”">​</a></h4><p>有許多方法可以配置你的 elementary OS（或者一般的 Linux 桌面），以達到延長電池壽命的目的。記住，電池壽命取決於你的筆記本硬件，以及電池和筆記本的使用年限。所以，遵循下面的一些建議，最大限度的利用你的筆記本電池。</p>',14)),a("ul",null,[a("li",null,[a("p",null,[e[6]||(e[6]=t("安裝 ",-1)),i(n,{href:"https://linrunner.de/tlp/"},{default:l(()=>[...e[5]||(e[5]=[t("tlp",-1)])]),_:1}),e[7]||(e[7]=t("。",-1)),e[8]||(e[8]=a("code",null,"tlp",-1)),e[9]||(e[9]=t(" 是一個簡單易用的命令列程序，用來幫你在 Linux 上延長電池壽命。你只需要安裝它，默認情況下，它會處理好其他的設置。安裝命令：",-1))]),e[10]||(e[10]=s(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:linrunner/tlp</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt-get install tlp</span></span>
<span class="line"><span>sudo tlp start</span></span></code></pre></div>`,1))]),e[11]||(e[11]=s('<li><p>關閉藍牙，默認情況下，藍牙是開啓狀態。在需要的時候再啓動它。</p></li><li><p>通過下面的命令安裝 <code>thermald</code>。這個實用程序（實際是個守護進程）控制着你的 CPU 的 P-States 和 T-States 的温度以及 CPU 發熱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install thermald</span></span></code></pre></div></li><li><p>根據你的需要將亮度調到最小。</p></li>',3))]),e[32]||(e[32]=s('<h4 id="_8、安裝磁盤實用程序" tabindex="-1">8、安裝磁盤實用程序 <a class="header-anchor" href="#_8、安裝磁盤實用程序" aria-label="Permalink to “8、安裝磁盤實用程序”">​</a></h4><p>在很多情況下，你發現你需要格式化 USB 或者向 USB 中寫入一些東西。默認情況下，系統沒有安裝任何相關的應用。你可以安裝以下這些易用的應用。</p><ul><li>gnome-disk-utility</li><li>gparted</li></ul><h4 id="_9、啓用最大化和最小化選項" tabindex="-1">9、啓用最大化和最小化選項 <a class="header-anchor" href="#_9、啓用最大化和最小化選項" aria-label="Permalink to “9、啓用最大化和最小化選項”">​</a></h4><p>許多用户喜歡在窗口標題欄左邊或者右邊使用最大化、最小化的按鈕，elementary OS 默認只提供關閉和恢復兩個選項。這沒什麼問題，因為這就是它的設計理念。然而你可以通過使用 Pantheon Tweaks 來開啓最大化和最小化按鈕，具體的方式是：“調整 &gt; 外觀 &gt; 窗口控制”。</p><p><img src="https://www.debugpoint.com/blog/wp-content/uploads/2021/08/enable-minimize-maximize-buttons-elementary-OS-1024x501.png" alt="在 elementary OS 中啓動最大化和最小化設置"></p><h4 id="_10、在-odin-中學習新的多點觸控手勢" tabindex="-1">10、在 Odin 中學習新的多點觸控手勢 <a class="header-anchor" href="#_10、在-odin-中學習新的多點觸控手勢" aria-label="Permalink to “10、在 Odin 中學習新的多點觸控手勢”">​</a></h4><p>如果你是筆記本用户，並且使用 elementary OS “Odin”，那麼你一定要看看這些超酷的新觸控手勢。三根手指向上滑動，就會平滑的打開多任務視圖，展示打開的應用程序和工作空間。用三根手指向左或向右滑動，就能在動態工作空間之間流暢的切換，使任務之間的切換更快。</p><p>用兩根手指也可以在原生應用中實現類似的功能。</p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>我希望這篇安裝 elementary OS 6 “Odin” 後要做的 10 件事能幫助到你，讓你可以上手使用 elementary OS 6 “Odin”，儘管這些事情完全是用户的偏好，因此這些事情有可能適合你也有可能不適用於你，但總的來説，這些都是一般用户喜歡的預期調整。</p><p>如果你覺得有更多的東西應該添加到列表中，請在下面的評論中告訴我。</p><hr>',13)),a("p",null,[e[13]||(e[13]=t("via: ",-1)),i(n,{href:"https://www.debugpoint.com/2021/08/10-things-to-do-after-install-elementary-os-6/"},{default:l(()=>[...e[12]||(e[12]=[t("https://www.debugpoint.com/2021/08/10-things-to-do-after-install-elementary-os-6/",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=t("作者：",-1)),i(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>[...e[14]||(e[14]=[t("Arindam",-1)])]),_:1}),e[19]||(e[19]=t(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 譯者：",-1)),i(n,{href:"https://github.com/anine09"},{default:l(()=>[...e[16]||(e[16]=[t("anine09",-1)])]),_:1}),e[21]||(e[21]=t(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[24]||(e[24]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...e[23]||(e[23]=[t("Linux中國",-1)])]),_:1}),e[26]||(e[26]=t(" 榮譽推出",-1))])])}const O=p(h,[["render",u]]);export{w as __pageData,O as default};
